def rrf(lists, k=60):
    s = {}
    for ranking in lists:
        for r, doc in enumerate(ranking, start=1):
            s[doc] = s.get(doc, 0) + 1 / (k + r)
    return sorted(s, key=s.get, reverse=True)

print(rrf([["A", "C", "D"], ["B", "E", "A"]]))  # A가 1등

import math
def dcg(rels):
    return sum(r / math.log2(i + 2) for i, r in enumerate(rels))
ranked = [0, 3, 2]
ideal = sorted(ranked, reverse=True)
print(round(dcg(ranked) / dcg(ideal), 2))   # 0.68
